package io.github.hador.datamask4j.spring;

/**
 * Application-owned secret-manager integration. Each call returns a fresh, caller-owned
 * byte array of at least 32 randomly generated bytes. The starter clears that array
 * after constructing its masker. Never return a shared backing array.
 */
@FunctionalInterface
public interface MaskingKeyProvider {
    byte[] loadKey();
}
